<?php
declare(strict_types=1);require_once dirname(__DIR__).'/bootstrap.php';
use Artdon\MaterialCenter\Services\AdaptationService;
$pageTitle='产品适配';$pageDescription='维护产品允许使用的电源、芯片、光学和配件规则。';$activeMenu='adaptation';$service=new AdaptationService();$products=$service->products(trim((string)($_GET['q']??'')));$selected=(int)($_GET['product_id']??($products[0]['id']??0));$groups=$selected?$service->groups($selected):[];$activeGroup=(int)($_GET['group_id']??($groups[0]['id']??0));$options=$activeGroup?$service->options($activeGroup):[];include MC_ROOT.'/components/layout_top.php';?>
<section class="mc-page mc-page--adaptation" data-adaptation><div class="mc-page-header mc-page-header--compact"><div><h1>产品适配</h1><p>产品只读来自命名系统；规则、审批和日志只写 mc_ 表。</p></div><form data-adaptation-action><input type="hidden" name="csrf_token" value="<?=mc_h(csrf_token())?>"><input type="hidden" name="action" value="sync"><button class="mc-button mc-button--primary">同步产品</button></form></div><div class="mc-adaptation-tabs"><button class="is-active">适配总览</button><button>电源</button><button>芯片</button><button>光学</button><button>配件</button><button>包装</button><button>冲突与待审批</button></div><div class="mc-adaptation-grid"><aside class="mc-product-list"><form><label class="mc-search mc-search--small"><?=mc_icon('search',16)?><input name="q" value="<?=mc_h($_GET['q']??'')?>" placeholder="搜索型号 / 名称"></label></form><div class="mc-product-list__items"><?php if(!$products):?><div class="mc-empty-state"><strong>尚未同步产品</strong></div><?php endif;foreach($products as$product):?><a class="<?=$selected===$product['id']?'is-active':''?>" href="?product_id=<?=intval($product['id'])?>"><span class="mc-product-thumb"><?=mc_icon('box',20)?></span><span><strong><?=mc_h($product['product_code']??'—')?></strong><small><?=mc_h($product['product_name']??'—')?></small><em><?=intval($product['group_count'])?> 组 · <?=intval($product['conflict_count'])?> 冲突</em></span></a><?php endforeach;?></div></aside><section class="mc-rule-canvas"><div class="mc-rule-canvas__header"><div><strong><?=mc_h(($products[array_search($selected,array_column($products,'id'))]['product_code']??'请选择产品'))?></strong><span>配置规则</span></div></div><div class="mc-rule-groups"><?php if(!$groups):?><div class="mc-empty-state"><strong>暂无配置组</strong><span>通过 API 或后续表单建立真实规则。</span></div><?php endif;foreach($groups as$group):?><a class="mc-rule-group <?=$activeGroup===$group['id']?'is-active':''?>" href="?product_id=<?=$selected?>&group_id=<?=intval($group['id'])?>"><span class="mc-rule-group__icon"><?=mc_icon('settings',18)?></span><span><strong><?=mc_h($group['group_name'])?></strong><small>默认：<?=mc_h($group['default_material']??'未设置')?></small></span><em><?=mc_h($group['status'])?></em><b><?=intval($group['option_count'])?> 个选项</b></a><?php endforeach;?></div></section><aside class="mc-option-panel"><div class="mc-option-panel__header"><div><strong>选项列表</strong><span>真实批准状态、价格和交期影响</span></div></div><div class="mc-option-list"><?php if(!$options):?><div class="mc-empty-state"><strong>暂无选项</strong></div><?php endif;foreach($options as$option):?><div><strong><?=mc_h($option['material_code'].' '.$option['name'])?></strong><small><?=mc_h(($option['brand']??'').' '.($option['model']??''))?> · 价格 <?=mc_h($option['price_impact']??'0')?> · 交期 <?=mc_h($option['lead_time_impact_days']??'0')?> 天</small><em class="mc-badge"><?=$option['is_default']?'默认':mc_h($option['option_type'])?></em></div><?php endforeach;?></div></aside></div></section><script src="<?=mc_h(mc_url('assets/js/adaptation-shell.js'))?>" defer></script><?php include MC_ROOT.'/components/layout_bottom.php';?>
